t.script:
(function() {
    'use strict';

    // Initialize all custom searchable selects (solo nivel 1 para categorías)
    function initAllCustomSelects() {
        document.querySelectorAll('.directory-custom-select:not([data-enhanced="true"])').forEach(function(select) {
            // Solo inicializar custom select para zonas y catLevel1
            if (select.id === 'zoneSelect' || select.id === 'catLevel1') {
                initCustomSelect(select);
            }
        });
    }

    function initCustomSelect(select) {
        var isZoneSelect = select.id === 'zoneSelect';
        var isCategorySelect = select.id === 'catLevel1';
        var form = select.closest('form');

        // Mark as enhanced
        select.dataset.enhanced = 'true';

        // Create wrapper - needs relative positioning for absolute dropdown
        var wrapper = document.createElement('div');
        wrapper.className = 'custom-searchable-select';
        // Zone select has higher z-index than category select
        var zIndex = isZoneSelect ? '100000' : '9999';
        wrapper.style.cssText = 'position:relative;display:block;z-index:' + zIndex + ';';
        wrapper.dataset.selectType = isZoneSelect ? 'zone' : 'category';

        // Ensure wrapper parent has visible overflow
        var parentContainer = select.closest('.card-body');
        if (parentContainer) {
            parentContainer.style.overflow = 'visible';
        }

        // Create toggle button
        var toggle = document.createElement('button');
        toggle.type = 'button';
        toggle.className = 'form-select text-start';
        var selectedOption = select.options[select.selectedIndex];
        var selectedText = selectedOption ? selectedOption.text : (isZoneSelect ? 'Seleccione zona...' : 'Todas las categorías');
        toggle.innerHTML = '<span class="selected-text">' + selectedText + '</span>';
        toggle.style.cssText = 'position:relative;width:100%;background:#fff;';

        // Create dropdown - use absolute positioning relative to wrapper
        var dropdown = document.createElement('div');
        dropdown.className = 'custom-select-dropdown';
        dropdown.style.cssText = 'position:absolute;z-index:99999;background:#fff;border:1px solid #ced4da;border-radius:0.375rem;width:100%;max-height:350px;overflow:hidden;display:none;box-shadow:0 0.5rem 1rem rgba(0,0,0,0.25);top:100%;left:0;margin-top:2px;';

        // Create search input
        var searchContainer = document.createElement('div');
        searchContainer.className = 'p-2 border-bottom';
        var placeholder = isZoneSelect ? 'Buscar zona...' : 'Buscar categoría...';
        searchContainer.innerHTML = '<input type="text" class="form-control form-control-sm" placeholder="' + placeholder + '" autocomplete="off">';
        var searchInput = searchContainer.querySelector('input');

        // Create options list
        var list = document.createElement('div');
        list.className = 'custom-select-options';
        list.style.cssText = 'max-height:280px;overflow-y:auto;-webkit-overflow-scrolling:touch;';

        // Build options
        Array.from(select.options).forEach(function(opt, index) {
            var item = document.createElement('div');
            item.className = 'custom-select-option';
            if (index === 0) item.classList.add('text-muted');
            item.textContent = opt.text;
            item.dataset.value = opt.value;
            item.dataset.url = opt.dataset.url || '';
            item.style.cssText = 'padding:10px 16px;cursor:pointer;transition:background 0.15s;font-size:14px;border-bottom:1px solid #f0f0f0;';
            item.addEventListener('mouseenter', function() { item.style.background = '#e9ecef'; });
            item.addEventListener('mouseleave', function() { item.style.background = 'transparent'; });
            item.addEventListener('click', function(e) {
                e.stopPropagation();

                // Update select value
                select.value = opt.value;

                // Update toggle text
                toggle.querySelector('.selected-text').textContent = opt.text;

                // Close dropdown
                dropdown.style.display = 'none';

                // Handle zone navigation or form submit
                if (isZoneSelect && opt.dataset.url) {
                    // Navigate to zone URL
                    window.location.href = opt.dataset.url;
                } else if (select.classList.contains('directory-cat-select')) {
                    // Trigger change event for category cascade
                    // Update selected attribute on options to match native behavior
                    Array.from(select.options).forEach(function(opt) {
                        opt.selected = (opt.value === select.value);
                    });
                    // Dispatch the change event synchronously
                    var changeEvent = new Event('change', { bubbles: true, cancelable: true });
                    select.dispatchEvent(changeEvent);
                } else if (form) {
                    // Submit form for categories
                    form.submit();
                }
            });
            list.appendChild(item);
        });

        // Search functionality
        searchInput.addEventListener('input', function() {
            var term = this.value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
            list.querySelectorAll('.custom-select-option').forEach(function(item) {
                var text = item.textContent.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                item.style.display = text.includes(term) ? 'block' : 'none';
            });
        });

        // Position dropdown - for absolute positioning relative to wrapper
        function positionDropdown() {
            // With absolute positioning, the dropdown is already positioned
            // relative to the wrapper. We just need to check if it overflows
            // the viewport and adjust if necessary.
            var rect = toggle.getBoundingClientRect();
            var viewportHeight = window.innerHeight;
            var dropdownHeight = Math.min(250, list.scrollHeight + 50); // approximate height

            // Check if dropdown would go below viewport
            var spaceBelow = viewportHeight - rect.bottom;

            if (spaceBelow < dropdownHeight && rect.top > dropdownHeight) {
                // Show above the toggle
                dropdown.style.top = 'auto';
                dropdown.style.bottom = '100%';
                dropdown.style.marginTop = '0';
                dropdown.style.marginBottom = '2px';
            } else {
                // Show below the toggle (default)
                dropdown.style.top = '100%';
                dropdown.style.bottom = 'auto';
                dropdown.style.marginTop = '2px';
                dropdown.style.marginBottom = '0';
            }
        }

        // Toggle dropdown
        toggle.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            var isOpen = dropdown.style.display === 'block';
            // Close all other dropdowns
            document.querySelectorAll('.custom-select-dropdown').forEach(function(d) { 
                if (d !== dropdown) d.style.display = 'none'; 
            });
            if (!isOpen) {
                positionDropdown();
                dropdown.style.display = 'block';
                searchInput.focus();
            }
        });

        // Reposition on resize only (scroll not needed with absolute positioning)
        window.addEventListener('resize', function() {
            if (dropdown.style.display === 'block') {
                positionDropdown();
            }
        }, { passive: true });

        // Close on outside click
        document.addEventListener('click', function(e) {
            if (!dropdown.contains(e.target) && e.target !== toggle) {
                dropdown.style.display = 'none';
            }
        });

        // Prevent closing when clicking inside dropdown
        dropdown.addEventListener('click', function(e) {
            if (e.target !== searchInput) e.stopPropagation();
        });

        // Assemble - append dropdown to wrapper for absolute positioning
        dropdown.appendChild(searchContainer);
        dropdown.appendChild(list);
        wrapper.appendChild(dropdown);

        wrapper.appendChild(toggle);

        // Replace select
        select.style.display = 'none';
        select.parentNode.insertBefore(wrapper, select);
        wrapper.appendChild(select);
    }

    // Initialize on DOM ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            // IMPORTANT: Initialize category cascade FIRST (before custom selects)
            // so event listeners are attached to the original select elements
            initCategoryCascade();
            initAllCustomSelects();
            initAsyncSearch();
        });
    } else {
        initCategoryCascade();
        initAllCustomSelects();
        initAsyncSearch();
    }

    // Async Search Functionality
    function initAsyncSearch() {
        var searchForm = document.getElementById('directorySearchForm');
        var searchInput = document.getElementById('directorySearchInput');
        var searchLoading = document.getElementById('searchLoading');
        var resultsContainer = document.getElementById('entries_grid') || document.getElementById('entries_list');

        if (!searchForm || !searchInput || !resultsContainer) {
            console.log('[Directory] Async search elements not found');
            return;
        }

        var searchTimeout;
        var minSearchLength = 3;
        var searchDelay = 400;

        searchInput.addEventListener('input', function() {
            clearTimeout(searchTimeout);
            var query = this.value.trim();

            if (query.length >= minSearchLength) {
                searchTimeout = setTimeout(function() {
                    performAjaxSearch(query);
                }, searchDelay);
            } else if (query.length === 0) {
                window.location.reload();
            }
        });

        searchForm.addEventListener('submit', function(e) {
            var query = searchInput.value.trim();
            if (query.length >= minSearchLength) {
                e.preventDefault();
                performAjaxSearch(query);
            }
        });

        function performAjaxSearch(query) {
            if (searchLoading) searchLoading.style.display = 'block';

            var xhr = new XMLHttpRequest();
            var viewType = document.querySelector('#entries_grid') ? 'grid' : 'list';
            var silverLevel = document.getElementById('directorySearchSilverLevel') ? document.getElementById('directorySearchSilverLevel').value : '';
            var sustainAction = document.getElementById('directorySearchSustainAction') ? document.getElementById('directorySearchSustainAction').value : '';
            var silverAction = document.getElementById('directorySearchSilverAction') ? document.getElementById('directorySearchSilverAction').value : '';
            var url = '/directorio/ajax/search?search=' + encodeURIComponent(query) + '&view=' + viewType;
            if (silverLevel) {
                url += '&silver_level=' + encodeURIComponent(silverLevel);
            }
            if (sustainAction) {
                url += '&sustain_action=' + encodeURIComponent(sustainAction);
            }
            if (silverAction) {
                url += '&silver_action=' + encodeURIComponent(silverAction);
            }

            xhr.open('GET', url, true);
            xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');

            xhr.onload = function() {
                if (searchLoading) searchLoading.style.display = 'none';
                if (xhr.status === 200) {
                    resultsContainer.innerHTML = xhr.responseText;
                }
            };

            xhr.onerror = function() {
                if (searchLoading) searchLoading.style.display = 'none';
            };

            xhr.send();
        }
    }

    // Robust global clear functions (do NOT depend on initCategoryCascade locals)
    window.clearSearchFilter = function() {
        console.log('[Directory] Clearing search filter');
        var searchInput = document.getElementById('directorySearchInput');
        if (searchInput) {
            searchInput.value = '';
            searchInput.dispatchEvent(new Event('input'));
        }
    };

    window.clearCategoryFilter = function() {
        console.log('[Directory] Clearing category filter');
        var level1Select = document.getElementById('catLevel1');
        var level2Select = document.getElementById('catLevel2');
        var level3Select = document.getElementById('catLevel3');
        var level2Container = document.getElementById('catLevel2Container');
        var level3Container = document.getElementById('catLevel3Container');

        if (level1Select) level1Select.value = '';
        if (level2Select) level2Select.value = '';
        if (level3Select) level3Select.value = '';

        if (level2Container) {
            level2Container.style.opacity = '0';
            setTimeout(function() { level2Container.style.display = 'none'; }, 300);
        }
        if (level3Container) {
            level3Container.style.opacity = '0';
            setTimeout(function() { level3Container.style.display = 'none'; }, 300);
        }

        var customToggle = document.querySelector('.custom-searchable-select[data-select-type="category"] .selected-text');
        if (customToggle) customToggle.textContent = 'Todas las categorías';

        var badgeSection = document.getElementById('activeCategoryBadge');
        if (badgeSection) badgeSection.style.display = 'none';

        // Trigger reload preserving filter params
        var searchInput = document.getElementById('directorySearchInput');
        if (searchInput && !searchInput.value.trim()) {
            var url = '/directorio?';
            var sl = document.getElementById('directorySearchSilverLevel') ? document.getElementById('directorySearchSilverLevel').value : '';
            var sa = document.getElementById('directorySearchSustainAction') ? document.getElementById('directorySearchSustainAction').value : '';
            var sia = document.getElementById('directorySearchSilverAction') ? document.getElementById('directorySearchSilverAction').value : '';
            var params = [];
            if (sl) params.push('silver_level=' + sl);
            if (sa) params.push('sustain_action=' + sa);
            if (sia) params.push('silver_action=' + sia);
            window.location.href = params.length ? url + params.join('&') : '/directorio';
        } else {
            window.clearSearchFilter();
        }
    };

    // Category Cascade Functionality with AJAX (Async)
    function initCategoryCascade(attempt) {
        attempt = attempt || 1;
        var catData = window.directoryCategories || [];
        var level1Select = document.getElementById('catLevel1');
        var level2Select = document.getElementById('catLevel2');
        var level3Select = document.getElementById('catLevel3');
        var level2Container = document.getElementById('catLevel2Container');
        var level3Container = document.getElementById('catLevel3Container');
        var form = document.getElementById('categoryFilterForm');
        var loader = document.getElementById('categoryLoader');
        var progress = document.getElementById('categoryProgress');
        var resultsContainer = document.getElementById('entries_grid') || document.getElementById('entries_list');

        if (!level1Select || !catData.length) {
            if (attempt < 10) {
                console.log('[Directory] No cat data or level1 select, retrying in 100ms (attempt ' + attempt + ')');
                setTimeout(function() { initCategoryCascade(attempt + 1); }, 100);
                return;
            }
            console.log('[Directory] No cat data or level1 select after 10 attempts, giving up');
            return;
        }

        if (window._directoryCategoryCascadeInitialized) {
            console.log('[Directory] Category cascade already initialized, skipping');
            return;
        }
        window._directoryCategoryCascadeInitialized = true;

        console.log('[Directory] Initializing category cascade with', catData.length, 'categories');

        // Helper to get current select value (handles both native and custom selects)
        function getSelectValue(select) {
            return select ? select.value : '';
        }

        // Helper to set select value programmatically
        function setSelectValue(select, value) {
            if (!select) return;
            select.value = value;
            // Update selected attribute on options
            Array.from(select.options).forEach(function(opt) {
                opt.selected = (opt.value === String(value));
            });
        }

        // Get selected values from server
        var selectedGrandparent = window.selectedCategoryGrandparent;
        var selectedParent = window.selectedCategoryParent;
        var selectedCat = window.selectedCategory;

        // Initialize level 2 if grandparent is selected
        if (selectedGrandparent) {
            var grandparent = catData.find(function(c) { return c.id === selectedGrandparent; });
            if (grandparent && grandparent.children.length) {
                populateSelect(level2Select, grandparent.children, 'Seleccione subcategoría...');
                showContainer(level2Container);
                if (selectedParent) {
                    setSelectValue(level2Select, selectedParent);
                }
            }
        }

        // Initialize level 3 if parent is selected
        if (selectedParent) {
            var grandparent = catData.find(function(c) { return c.id === selectedGrandparent; });
            if (grandparent) {
                var parent = grandparent.children.find(function(c) { return c.id === selectedParent; });
                if (parent && parent.children.length) {
                    populateSelect(level3Select, parent.children, 'Seleccione especialidad...');
                    showContainer(level3Container);
                    updateHint(2, parent.name);
                    if (selectedCat) {
                        setSelectValue(level3Select, selectedCat);
                    }
                }
            }
        }

        // Prevent form submit (we use AJAX)
        if (form) {
            form.addEventListener('submit', function(e) {
                e.preventDefault();
                console.log('[Directory] Form submit prevented, using AJAX');
            });
        }

        // Attach change listeners DIRECTLY to each select to avoid bubbling issues
        function attachSelectChange(select, handler) {
            if (!select) return;
            select.addEventListener('change', function(e) {
                console.log('[Directory] Direct change event on', select.id, 'value:', select.value);
                handler(select.value);
            });
        }
        attachSelectChange(level1Select, handleLevel1Change);
        attachSelectChange(level2Select, handleLevel2Change);
        attachSelectChange(level3Select, handleLevel3Change);

        // Also keep form delegation as fallback
        if (form) {
            form.addEventListener('change', function(e) {
                var target = e.target;
                if (target && (target.id === 'catLevel1' || target.id === 'catLevel2' || target.id === 'catLevel3')) {
                    console.log('[Directory] Delegated change event on', target.id, 'value:', target.value);
                }
            });
        }

        // Update sidebar filter badges
        function updateSidebarFilterBadge(categoryName, categoryId) {
            var badgeSection = document.getElementById('activeCategoryBadge');
            if (!badgeSection) return;

            if (categoryName && categoryId) {
                // Show the section
                badgeSection.style.display = 'block';
                // Update the badge text
                var badge = badgeSection.querySelector('.badge.bg-primary, .badge.bg-success');
                if (badge) {
                    badge.innerHTML = '<i class="fa fa-folder-open me-1"></i>' + categoryName;
                }
            } else {
                // Hide the section
                badgeSection.style.display = 'none';
            }
        }

        // Global functions are defined outside initCategoryCascade for robustness
        // (see window.clearCategoryFilter and window.clearSearchFilter below)

        function handleLevel1Change(value) {
            var grandparentId = parseInt(value) || null;
            console.log('[Directory] Level 1 changed to:', grandparentId);

            // Hide lower levels first
            hideContainer(level2Container);
            hideContainer(level3Container);

            if (!grandparentId) {
                // Clear filter - use current state
                showLoader();
                performCategoryAjaxSearch(null, 1, currentFilterState.viewType, currentFilterState.ppg);
                return;
            }

            var grandparent = catData.find(function(c) { return c.id === grandparentId; });
            console.log('[Directory] Found grandparent:', grandparent ? grandparent.name : 'null', 'children:', grandparent ? grandparent.children.length : 0);

            // ALWAYS do AJAX search immediately for selected category
            console.log('[Directory] Doing AJAX search for level 1');
            showLoader();
            performCategoryAjaxSearch(grandparentId, 1, currentFilterState.viewType, currentFilterState.ppg);

            // Update sidebar badge
            if (grandparent) {
                updateSidebarFilterBadge(grandparent.name, grandparentId);
            }

            // Also show children if they exist (for further refinement)
            if (grandparent && grandparent.children.length) {
                console.log('[Directory] Also showing level 2 with', grandparent.children.length, 'children');
                populateSelect(level2Select, grandparent.children, 'Seleccione subcategoría...');
                showContainer(level2Container);
                updateHint(1, grandparent.name);
            }
        }

        function handleLevel2Change(value) {
            var parentId = parseInt(value) || null;
            console.log('[Directory] Level 2 changed to:', parentId);

            // Hide level 3
            hideContainer(level3Container);

            if (!parentId) {
                // Go back to level 1 value
                var grandparentId = parseInt(getSelectValue(level1Select)) || null;
                if (grandparentId) {
                    showLoader();
                    performCategoryAjaxSearch(grandparentId, 1, currentFilterState.viewType, currentFilterState.ppg);
                }
                return;
            }

            var grandparentId = parseInt(getSelectValue(level1Select)) || null;
            var grandparent = catData.find(function(c) { return c.id === grandparentId; });
            if (!grandparent) return;

            var parent = grandparent.children.find(function(c) { return c.id === parentId; });

            // ALWAYS do AJAX search immediately for selected category
            console.log('[Directory] Doing AJAX search for level 2');
            showLoader();
            performCategoryAjaxSearch(parentId, 1, currentFilterState.viewType, currentFilterState.ppg);

            // Update sidebar badge
            if (parent) {
                updateSidebarFilterBadge(parent.name, parentId);
            }

            // Also show children if they exist (for further refinement)
            if (parent && parent.children.length) {
                console.log('[Directory] Also showing level 3 with', parent.children.length, 'children');
                populateSelect(level3Select, parent.children, 'Seleccione especialidad...');
                showContainer(level3Container);
                updateHint(2, parent.name);
            }
        }

        function handleLevel3Change(value) {
            var catId = parseInt(value) || null;
            console.log('[Directory] Level 3 changed to:', catId);
            if (catId) {
                showLoader();
                performCategoryAjaxSearch(catId, 1, currentFilterState.viewType, currentFilterState.ppg);

                // Find category name and update sidebar badge
                var grandparentId = parseInt(getSelectValue(level1Select)) || null;
                var grandparent = catData.find(function(c) { return c.id === grandparentId; });
                if (grandparent) {
                    var parentId = parseInt(getSelectValue(level2Select)) || null;
                    var parent = grandparent.children.find(function(c) { return c.id === parentId; });
                    if (parent) {
                        var cat = parent.children.find(function(c) { return c.id === catId; });
                        if (cat) {
                            updateSidebarFilterBadge(cat.name, catId);
                        }
                    }
                }
            }
        }

        // Store current filter state
        var currentFilterState = {
            categoryId: getCurrentCategoryId(),
            viewType: 'grid',
            ppg: 21,
            page: 1
        };

        // Prevent duplicate AJAX requests
        var isAjaxLoading = false;

        // Helper to get current results container (grid or list)
        function getResultsContainer() {
            return document.getElementById('entries_grid') || document.getElementById('entries_list');
        }

        // Attach pagination handlers on initial load
        attachPaginationHandlers();

        // AJAX function for category search
        function performCategoryAjaxSearch(categoryId, page, viewType, ppg) {
            // Prevent duplicate requests
            if (isAjaxLoading) {
                console.log('[Directory] AJAX already in progress, skipping duplicate request');
                return;
            }

            // Use provided values or fall back to current state
            categoryId = categoryId !== undefined ? categoryId : currentFilterState.categoryId;
            page = page !== undefined ? page : currentFilterState.page;
            viewType = viewType !== undefined ? viewType : currentFilterState.viewType;
            ppg = ppg !== undefined ? ppg : currentFilterState.ppg;

            // Update current state
            currentFilterState.categoryId = categoryId;
            currentFilterState.page = page;
            currentFilterState.viewType = viewType;
            currentFilterState.ppg = ppg;

            isAjaxLoading = true;
            console.log('[Directory] performCategoryAjaxSearch called:', {categoryId, page, viewType, ppg});

            var xhr = new XMLHttpRequest();
            var silverLevel = document.getElementById('directorySearchSilverLevel') ? document.getElementById('directorySearchSilverLevel').value : '';
            var sustainAction = document.getElementById('directorySearchSustainAction') ? document.getElementById('directorySearchSustainAction').value : '';
            var silverAction = document.getElementById('directorySearchSilverAction') ? document.getElementById('directorySearchSilverAction').value : '';
            var url = '/directorio/ajax/search?view=' + viewType + '&ppg=' + ppg;
            if (categoryId) {
                url += '&category=' + categoryId;
            }
            if (page > 1) {
                url += '&page=' + page;
            }
            if (silverLevel) {
                url += '&silver_level=' + encodeURIComponent(silverLevel);
            }
            if (sustainAction) {
                url += '&sustain_action=' + encodeURIComponent(sustainAction);
            }
            if (silverAction) {
                url += '&silver_action=' + encodeURIComponent(silverAction);
            }
            console.log('[Directory] AJAX URL:', url);

            xhr.open('GET', url, true);
            xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');

            xhr.onload = function() {
                hideLoader();
                isAjaxLoading = false;
                console.log('[Directory] AJAX response status:', xhr.status);
                if (xhr.status === 200) {
                    // Get current container (may have changed after view type switch)
                    var container = getResultsContainer();
                    console.log('[Directory] Updating results container:', container ? container.id : 'null');
                    if (container) {
                        // First, remove ALL pagination elements (both AJAX and original) to avoid duplicates
                        var allPagsBefore = document.querySelectorAll('nav[aria-label="Navegación de páginas"]');
                        console.log('[Directory] Removing ALL paginations before update:', allPagsBefore.length);
                        allPagsBefore.forEach(function(nav) {
                            console.log('[Directory] Removing pagination:', nav.className);
                            nav.remove();
                        });
                        // Now update the container
                        container.innerHTML = xhr.responseText;
                        console.log('[Directory] Results updated successfully');
                    } else {
                        console.error('[Directory] resultsContainer not found!');
                    }
                    // Hide original pagination (from initial page load)
                    document.querySelectorAll('nav[aria-label="Navegación de páginas"]').forEach(function(nav) {
                        if (!nav.classList.contains('ajax-pagination')) {
                            nav.style.display = 'none';
                        }
                    });
                    // Re-attach pagination handlers
                    console.log('[Directory] Attaching pagination handlers');
                    attachPaginationHandlers();
                    // Update view type buttons
                    updateViewTypeButtons(viewType);
                    // Update items per page buttons
                    updateItemsPerPageButtons(ppg);
                    // Scroll to top of results
                    container = getResultsContainer();
                    if (container) {
                        container.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }
                    // Update URL without reloading
                    if (window.history && window.history.pushState) {
                        var newUrl = '/directorio';
                        var params = [];
                        if (categoryId) params.push('category=' + categoryId);
                        if (page > 1) params.push('page=' + page);
                        if (viewType !== 'grid') params.push('view=' + viewType);
                        if (ppg !== 21) params.push('ppg=' + ppg);
                        var sl = document.getElementById('directorySearchSilverLevel') ? document.getElementById('directorySearchSilverLevel').value : '';
                        var sa = document.getElementById('directorySearchSustainAction') ? document.getElementById('directorySearchSustainAction').value : '';
                        var sia = document.getElementById('directorySearchSilverAction') ? document.getElementById('directorySearchSilverAction').value : '';
                        if (sl) params.push('silver_level=' + sl);
                        if (sa) params.push('sustain_action=' + sa);
                        if (sia) params.push('silver_action=' + sia);
                        if (params.length) newUrl += '?' + params.join('&');
                        window.history.pushState({ categoryFilter: true }, document.title, newUrl);
                    }
                } else {
                    console.error('[Directory] AJAX error:', xhr.statusText);
                    window.location.href = url;
                }
            };

            xhr.onerror = function() {
                hideLoader();
                isAjaxLoading = false;
                console.error('[Directory] AJAX network error');
                window.location.href = url;
            };

            xhr.send();
        }

        // Attach handlers to pagination links
        function attachPaginationHandlers() {
            var pageLinks = document.querySelectorAll('.ajax-page-link');
            console.log('[Directory] Attaching handlers to', pageLinks.length, 'pagination links');
            pageLinks.forEach(function(link, idx) {
                // Remove existing listeners to avoid duplicates
                link.removeEventListener('click', handlePageClick);
                link.addEventListener('click', handlePageClick);
            });
        }

        function handlePageClick(e) {
            e.preventDefault();
            e.stopPropagation();
            var href = this.getAttribute('href');
            console.log('[Directory] Pagination clicked, href:', href);
            // Try to find page number in URL path first (/page/X), then in query string (?page=X)
            var pageMatch = href.match(/\/page\/(\d+)/) || href.match(/[?&]page=(\d+)/);
            var page = pageMatch ? parseInt(pageMatch[1]) : 1;
            console.log('[Directory] Going to page:', page);
            showLoader();
            performCategoryAjaxSearch(currentFilterState.categoryId, page, currentFilterState.viewType, currentFilterState.ppg);
        }

        // Global function to change items per page
        window.changeItemsPerPage = function(ppg) {
            console.log('[Directory] Changing items per page to:', ppg);
            showLoader();
            performCategoryAjaxSearch(currentFilterState.categoryId, 1, currentFilterState.viewType, ppg);
        };

        // Global function to change view type
        window.changeViewType = function(viewType) {
            console.log('[Directory] Changing view type to:', viewType);
            showLoader();
            performCategoryAjaxSearch(currentFilterState.categoryId, 1, viewType, currentFilterState.ppg);
        };

        // Update view type button styles
        function updateViewTypeButtons(viewType) {
            var gridBtn = document.querySelector('button[onclick="changeViewType(\'grid\')"]');
            var listBtn = document.querySelector('button[onclick="changeViewType(\'list\')"]');
            if (gridBtn) {
                gridBtn.className = viewType === 'grid' ? 'btn btn-sm btn-primary active' : 'btn btn-sm btn-outline-secondary';
            }
            if (listBtn) {
                listBtn.className = viewType === 'list' ? 'btn btn-sm btn-primary active' : 'btn btn-sm btn-outline-secondary';
            }
        }

        // Update items per page button styles
        function updateItemsPerPageButtons(ppg) {
            var buttons = document.querySelectorAll('button[onclick^="changeItemsPerPage"]');
            buttons.forEach(function(btn) {
                var match = btn.getAttribute('onclick').match(/changeItemsPerPage\((\d+)\)/);
                if (match) {
                    var btnPpg = parseInt(match[1]);
                    btn.className = btnPpg === ppg ? 'btn btn-sm btn-primary active' : 'btn btn-sm btn-outline-secondary';
                }
            });
        }

        // Get current category ID from URL or select
        function getCurrentCategoryId() {
            var urlParams = new URLSearchParams(window.location.search);
            return urlParams.get('category');
        }

        // Update hint text for category selection
        function updateHint(level, categoryName) {
            // Optional: show feedback about selected category
            console.log('[Directory] Selected level ' + level + ': ' + categoryName);
        }

        function showLoader() {
            if (loader) loader.style.display = 'inline-block';
            if (progress) progress.style.display = 'block';
            // Disable selects
            [level1Select, level2Select, level3Select].forEach(function(s) {
                if (s) s.disabled = true;
            });
        }

        function hideLoader() {
            if (loader) loader.style.display = 'none';
            if (progress) progress.style.display = 'none';
            // Enable selects
            [level1Select, level2Select, level3Select].forEach(function(s) {
                if (s) s.disabled = false;
            });
        }

        function showContainer(container) {
            if (!container) return;
            console.log('[Directory] Showing container:', container.id);
            // Cancel any pending hide operation
            if (container._hideTimeout) {
                clearTimeout(container._hideTimeout);
                container._hideTimeout = null;
            }
            container.style.display = 'block';
            container.style.opacity = '1';
        }

        function hideContainer(container) {
            if (!container) return;
            console.log('[Directory] Hiding container:', container.id);
            container.style.opacity = '0';
            // Store timeout reference so it can be cancelled
            container._hideTimeout = setTimeout(function() {
                container.style.display = 'none';
                container._hideTimeout = null;
            }, 300);
        }

        function populateSelect(select, items, placeholder) {
            // Clear existing options except first
            while (select.options.length > 1) {
                select.remove(1);
            }
            // Add new options
            items.forEach(function(item) {
                var option = document.createElement('option');
                option.value = item.id;
                option.textContent = item.name;
                select.appendChild(option);
            });
        }
    }
})();
